                <div class="category-overlay">惬意日常系列</div>
            </div>
            <div class="category-card" onclick="location.href='products.html'">
                <img src="https://images.unsplash.com/photo-1539109136881-3be0616acf45?auto=format&fit=crop&w=500&q=80" alt="经典款">
                <div class="category-overlay">永恒经典系列</div>
            </div>
        </div>
    </section>

    <footer>
        <div class="footer-container">
            <div class="footer-col">
                <h4>关于可衣</h4>
                <p style="font-size: 14px; color: var(--text-muted);">坐标上海。我们致力于为20-40岁的现代女性提供高品质、简约且不过时的服装。</p>
            </div>
            <div class="footer-col">
                <h4>客户服务</h4>
                <ul>
                    <li><a href="#">配送政策</a></li>
                    <li><a href="#">退换货指南</a></li>
                    <li><a href="#">常见问题</a></li>
                </ul>
            </div>
            <div class="footer-col">
                <h4>快速链接</h4>
                <ul>
                    <li><a href="products.html">所有商品</a></li>
                    <li><a href="index.html">首页</a></li>
                    <li><a href="cart.html">我的订单</a></li>
                </ul>
            </div>
            <div class="footer-col">
                <h4>联系我们</h4>
                <p style="font-size: 14px; color: var(--text-muted);">上海市静安区南京西路<br>邮箱: support@keyi-sh.com</p>
            </div>
