                    <td>专业干洗 / 温水手洗</td>
                </tr>
                <tr>
                    <td>产地</td>
                    <td>中国上海</td>
                </tr>
                <tr>
                    <td>配送时间</td>
                    <td>下单后 2-4 个工作日发货</td>
                </tr>
            </table>
        </div>
    </div>

    <script>
        function selectSize(btn) {
            document.querySelectorAll('.size-btn').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
        }

        function addToCart() {
            alert('商品已成功加入购物车！');
        }
    </script>

</body>
